//! Golden test: every vanilla carver (+ custom configurations) over a grid of target chunks with all source
//! chunks within +-8, replaying `NoiseBasedChunkGenerator.generateCarvers`' carver loop for several seeds,
//! dimension heights and carver indexes, against the vanilla classes (fixtures generated by
//! `tests/oracle/CarverOracle.java`). Compares start-chunk decisions, results, the random state after every
//! source chunk (rolling hash), the `CarvingMask` digest, the full carved set (subset) and the final random.

use std::collections::{BTreeMap, HashMap};
use std::io::Read;
use std::path::PathBuf;
use std::sync::Arc;

use mc_core::ident::Identifier;
use mc_core::pos::ChunkPos;
use mc_core::random::{LegacyRandomSource, RandomSource, WorldgenRandom};
use mc_world::carving_mask::CarvingMask;
use mc_worldgen::carver::{WorldCarver, carver_from_json};
use mc_worldgen::data::{FsDataSource, WorldgenRegistries};
use mc_worldgen::world_generation_context::WorldGenerationContext;

const VANILLA: [&str; 4] = ["cave", "cave_extra_underground", "canyon", "nether_cave"];

fn dims(name: &str) -> (i32, i32, i32) {
    match name {
        "overworld" => (-64, 384, 63),
        "nether" => (0, 128, 32),
        "custom" => (-32, 112, 10),
        other => panic!("unknown dim {other}"),
    }
}

fn data_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../ref/src/data")
}

#[test]
fn carvers_match_vanilla() {
    let registries = WorldgenRegistries::new(Arc::new(FsDataSource::new(data_root())));
    let mut carvers: HashMap<String, Arc<dyn WorldCarver>> = HashMap::new();
    for name in VANILLA {
        let id = Identifier::parse(&format!("minecraft:{name}")).unwrap();
        carvers.insert(name.to_string(), registries.carver(&id).unwrap());
    }

    let mut dumps: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut gz = flate2::read::GzDecoder::new(&include_bytes!("../fixtures/carver_masks.txt.gz")[..]);
    let mut text = String::new();
    gz.read_to_string(&mut text).unwrap();
    for line in text.lines() {
        // `S name dim seed index tx tz x z bottomY topY`: the key is everything up to tz.
        let parts: Vec<&str> = line.split(' ').collect();
        dumps
            .entry(parts[1..=6].join(" "))
            .or_default()
            .push(parts[7..].join(" "));
    }

    let (mut total_starts, mut total_blocks, mut checked_dumps, mut edge_cases) = (0i64, 0i64, 0, 0);
    for line in include_str!("../fixtures/carvers.txt").lines() {
        let (tag, rest) = line.split_once(' ').unwrap();
        if tag == "E" {
            let (status, json) = rest.split_once(' ').unwrap();
            let accepted = carver_from_json(&serde_json::from_str(json).unwrap()).is_ok();
            assert_eq!(accepted, status == "OK", "codec edge case: {json}");
            edge_cases += 1;
            continue;
        }
        if tag == "D" {
            let (name, json) = rest.split_once(' ').unwrap();
            let value = serde_json::from_str(json).unwrap();
            carvers.insert(name.to_string(), carver_from_json(&value).unwrap());
            continue;
        }
        assert_eq!(tag, "R");
        let f: Vec<&str> = rest.split(' ').collect();
        let (name, dim) = (f[0], f[1]);
        let seed: i64 = f[2].parse().unwrap();
        let index: i32 = f[3].parse().unwrap();
        let (tx, tz): (i32, i32) = (f[4].parse().unwrap(), f[5].parse().unwrap());
        let expected: Vec<i64> = f[6..].iter().map(|v| v.parse().unwrap()).collect();
        let ctx_label = format!("{name} {dim} seed {seed} index {index} target ({tx},{tz})");

        let (min_y, height, sea) = dims(dim);
        let context = WorldGenerationContext::of_level(min_y, height, sea);
        let carver = &carvers[name];
        let pos = ChunkPos::new(tx, tz);
        let mut mask = CarvingMask::new(min_y + 1, min_y + height - 1 - 7);
        let mut random = WorldgenRandom::new(Box::new(LegacyRandomSource::new(0)));
        let (mut starts, mut carves, mut hash) = (0i64, 0i64, 0i64);
        for dx in -8..=8 {
            for dz in -8..=8 {
                let source = ChunkPos::new(tx + dx, tz + dz);
                random.set_large_feature_seed(seed + i64::from(index), source.x, source.z);
                let start = carver.is_start_chunk(&mut random);
                let mut result = false;
                if start {
                    starts += 1;
                    result = carver.carve(&context, &mut random, pos, source, &mut mask);
                    if result {
                        carves += 1;
                    }
                }
                hash = hash
                    .wrapping_mul(31)
                    .wrapping_add(i64::from(start) + if result { 2 } else { 0 });
                hash = hash.wrapping_mul(31).wrapping_add(random.next_long());
            }
        }
        let after = random.next_long();
        let (mut segs, mut blocks, mut mask_hash) = (0i64, 0i64, 0i64);
        let mut segments = Vec::new();
        mask.visit(|x, z, bottom, top| {
            segs += 1;
            blocks += i64::from(top - bottom + 1);
            mask_hash = mask_hash.wrapping_mul(31).wrapping_add(
                (i64::from(x) << 40)
                    ^ (i64::from(z) << 32)
                    ^ (i64::from(bottom + 100000) << 16)
                    ^ i64::from(top + 100000),
            );
            segments.push(format!("{x} {z} {bottom} {top}"));
        });
        assert_eq!(
            vec![starts, carves, hash, segs, blocks, mask_hash, after],
            expected,
            "{ctx_label}"
        );
        total_starts += starts;
        total_blocks += blocks;
        if seed == 12345 && index == 0 {
            let key = format!("{name} {dim} {seed} {index} {tx} {tz}");
            let expected_segments = dumps.get(&key).cloned().unwrap_or_default();
            assert_eq!(segments, expected_segments, "{ctx_label}: carved set");
            checked_dumps += 1;
        }
    }
    // Not vacuous: plenty of carvers started and carved blocks.
    assert!(total_starts > 1000 && total_blocks > 1_000_000 && checked_dumps > 100);
    assert!(edge_cases > 30);
}

#[test]
fn registry_loading_is_memoized_and_reports_missing_entries() {
    let registries = WorldgenRegistries::new(Arc::new(FsDataSource::new(data_root())));
    let id = Identifier::parse("minecraft:canyon").unwrap();
    let a = registries.carver(&id).unwrap();
    let b = mc_worldgen::carver::load_carver(&registries, &id).unwrap();
    assert!(Arc::ptr_eq(&a, &b));
    assert_eq!(a.get_range(), 4);
    let missing = Identifier::parse("minecraft:nope").unwrap();
    let error = registries.carver(&missing).err().unwrap().to_string();
    assert_eq!(error, "worldgen/carver/minecraft:nope: no such registry entry");
}
